import assert from 'node:assert/strict';
import { spawnSync } from 'node:child_process';
import fs from 'node:fs';
import os from 'node:os';
import path from 'node:path';
import test from 'node:test';
import { fileURLToPath } from 'node:url';
import { buildRoadNetwork } from '../js/road-network.js';
import { gfRoadSource } from '../js/gf-roadgraph.js';
import { GF_GEO } from '../js/gf-geodata.js';
import { GF_SIGNALS } from '../js/gf-signals.js';

// Glens Falls traffic signals: js/gf-signals.js, generated by tools/gf/build-gf-signals.mjs from the OSM extract in
// tools/gf/data/osm_gf_signals.json, and the junctions of the road network they signal

const root = fileURLToPath(new URL('../', import.meta.url));

test('gf-signals.js is regenerated byte for byte from the raw extract', () => {
  const dir = fs.mkdtempSync(path.join(os.tmpdir(), 'gf-signals '));
  try {
    const out = path.join(dir, 'gf-signals.js');
    const result = spawnSync(process.execPath, [path.join(root, 'tools/gf/build-gf-signals.mjs'), out], { encoding: 'utf8' });
    assert.ifError(result.error);
    assert.equal(result.status, 0, result.stderr + result.stdout);
    assert.ok(fs.readFileSync(out).equals(fs.readFileSync(path.join(root, 'js/gf-signals.js'))), 'js/gf-signals.js is stale');
  } finally {
    fs.rmSync(dir, { recursive: true, force: true });
  }
});

test('51 junction signals and 24 signalled crossings, inside the bbox, each junction on a road graph node', () => {
  const { junctions, crossings } = GF_SIGNALS;
  assert.equal(junctions.length, 51);
  assert.equal(crossings.length, 24);
  assert.match(GF_SIGNALS.attribution, /© OpenStreetMap contributors/);
  const { x0, x1, z0, z1 } = GF_GEO.bbox;
  for (const [x, z] of [...junctions, ...crossings]) assert.ok(x >= x0 && x <= x1 && z >= z0 && z <= z1, `(${x}, ${z})`);
  const ids = (list) => list.map((s) => s[2]);
  assert.deepEqual(ids(junctions), ids(junctions).slice().sort((a, b) => a - b), 'junctions sorted by OSM id');
  assert.deepEqual(ids(crossings), ids(crossings).slice().sort((a, b) => a - b), 'crossings sorted by OSM id');
  for (const [, , , direction] of junctions) assert.ok(direction === null || ['forward', 'backward', 'both'].includes(direction));
  const { nodes } = GF_GEO.roadGraph;
  for (const [x, z, id] of junctions) {
    let d = Infinity;
    for (let i = 0; i < nodes.length; i += 2) d = Math.min(d, Math.hypot(nodes[i] - x, nodes[i + 1] - z));
    assert.ok(d <= 0.5, `junction ${id} is ${d.toFixed(2)} m from the nearest road graph node`);
  }
});

test('the network signals the junctions OSM signals (41 nodes), never a shape node, each within 6 m of one', () => {
  const info = console.info;
  console.info = () => {};
  let network;
  try {
    network = buildRoadNetwork([], [], GF_SIGNALS.junctions.map(([x, z]) => ({ x, z })), gfRoadSource(GF_GEO));
  } finally {
    console.info = info;
  }
  const signalled = network.nodes.filter((n) => n.signal);
  assert.equal(signalled.length, 41);
  for (const n of signalled) {
    assert.ok(!n.shape, `node ${n.id} is a bend`);
    assert.ok(GF_SIGNALS.junctions.some(([x, z]) => Math.abs(n.x - x) < 6 && Math.abs(n.z - z) < 6), `node ${n.id} has no OSM signal`);
  }
});
